    public OrderDto get(@PathVariable String id) {
        OrderDto dto = queryGateway.query(new FindOrder(id), ResponseTypes.instanceOf(OrderDto.class)).join();
        if (dto == null) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND);
        }
